{"path":"treatment/check_web_launch_readiness.ts","encoding":"utf-8","content":"#!/usr/bin/env tsx
/**
 * `check_web_launch_readiness` — the web-surface pre-ship audit, as a COMMAND.
 *
 * NOT a skill, and the container is a recorded decision rather than a default.
 * AI council 2/2 on 2026-08-25 (`road-to-web-launch-readiness`
 * § `b-estate-decision-web-launch`): the G0 evidence establishes a COVERAGE gap,
 * not a SKILL-SHAPED one. A site-type-conditional config, deterministic checks,
 * tiers and a hard pass/fail gate are *"the signature of a linter, not a skill"*,
 * and `production-validator` carries unscoped `Bash`, so it can invoke this
 * directly instead of depending on skill activation — which demonstrably is NOT
 * firing for web-facing deploys, since `launch-readiness` already exists and
 * scores 0 of 8 on these axes.
 *
 * CONDITIONAL, NOT FLAT. Every check declares `applies_to`, and a check that does
 * not apply is reported as **skipped with the site type as the reason** — never
 * silently dropped and never as a finding. A reader must be able to tell "this
 * does not apply to you" from "this passed", which a flat audit cannot express.
 *
 * DEFAULT-OFF until the pre-registered benchmark returns positive
 * (`claim:web-launch-readiness-finds-more`, status `unbacked`). Absent the
 * opt-in, this exits 0 and says why rather than auditing.
 *
 * Exit codes: 0 = no critical/high finding and nothing left undecided (or not
 * enabled) · 1 = a blocking finding, OR an applicable check the instrument could
 * not decide · 2 = usage or a dead scan scope.
 */
import * as fs from 'node:fs';
import * as path from 'node:path';
import process from 'node:process';
import { fileURLToPath } from 'node:url';

import { asOf } from './_lib/as_of.js';
import { DeadScopeError, reportScanned } from './_lib/scan_scope.js';
import {
    type OriginRow,
    type Supersession,
    type ThirdPartyCtx,
    classifyLoads,
    legalPagePlaceholders,
    loadRegister,
    privacyCoverage,
    supersededStatute,
} from './web_launch_third_party.js';
import { resolveOrigin } from './web_launch_third_party.js';
import { type Witness, renderWitness } from './web_launch_render.js';
import { HEAD_TAGS, attr, tagsOf, titleOf } from './_lib/html_tags.js';
import { canonicalAndSitemap, structuredDataParses } from './web_launch_head_checks.js';
import { type CrawlerRow, indexability, loadCrawlerRegister, snippetBlocks } from './web_launch_crawlers.js';

const HERE = fileURLToPath(import.meta.url);
const REPO_ROOT = path.resolve(path.dirname(HERE), '..', '..');
export const CONFIG_REL = 'src/config/web-launch-readiness.json';

export type SiteType = 'local-business' | 'marketing-site' | 'saas-app' | 'docs' | 'internal-tool';
export type Tier = 'critical' | 'high' | 'medium' | 'situational';
/**
 * The region axis (2.3), and it is deliberately NOT a second `applies_to`.
 *
 * `applies_to` decides WHETHER a check applies; a region decides HOW SEVERELY.
 * A legal page is not more or less *applicable* in Germany — it is more or less
 * *optional*, because German and EU law make it owed rather than advisable. The
 * two citations behind that sentence are NOT restated here: they live in the
 * escalation row's `authority` field in `web-launch-readiness.json`, where a
 * `review_by` date can lapse them. That is the whole point of the
 * `ddg-citation-authority` decision — a statute in prose cited law already dead
 * for twenty-seven months and nothing could see it.
 * Modelling it as a tier escalation keeps one check with one implementation and
 * puts the jurisdiction where it belongs: on the consequence.
 */
export type Region = 'de' | 'eu' | 'us' | 'unspecified';

export interface CheckDef {
    id: string;
    title: string;
    applies_to: SiteType[];
    tier: Tier;
    why: string;
    remediation: string;
    verification: string;
    /** Statute + where it can be read. Required once the row asserts a legal basis. */
    authority?: string;
    /** ISO date the citation must be re-read by. A lapsed date FAILS the loader. */
    review_by?: string;
    /** What the verdict rests on: an operator or standards page, a stated practice, or this estate's own evidence. */
    basis: Basis;
}

export const BASIS_LEVELS = ['official', 'heuristic', 'estate'] as const;
export type BasisLevel = (typeof BASIS_LEVELS)[number];
export interface Basis {
    level: BasisLevel;
    ref: string;
    checked_at: string;
}

/** Each check carries a complete `basis`; an `official` one cites a URL a reader can open. Empty = valid. */
export function basisViolations(checks: readonly { id: string; basis?: Partial<Basis> }[]): string[] {
    const out: string[] = [];
    for (const c of checks) {
        const where = `check "${c.id}"`;
        const b = c.basis;
        if (b === undefined) {
            out.push(`${where}: no \`basis\` — a check says what its verdict rests on`);
            continue;
        }
        if (!BASIS_LEVELS.includes(b.level as BasisLevel)) out.push(`${where}: basis.level "${String(b.level)}" is not one of ${BASIS_LEVELS.join(', ')}`);
        if (typeof b.ref !== 'string' || b.ref.trim().length < 10) out.push(`${where}: basis.ref is empty or too short to be re-checked`);
        else if (b.level === 'official' && !/https:\/\/\S+/.test(b.ref)) out.push(`${where}: an official basis.ref must cite an https URL`);
        if (typeof b.checked_at !== 'string' || !ISO_DATE_RE.test(b.checked_at) || Number.isNaN(Date.parse(b.checked_at))) {
            out.push(`${where}: basis.checked_at is not a YYYY-MM-DD date`);
        }
    }
    return out;
}

export interface Finding {
    check: string;
    tier: Tier;
    /** `path:line` — the step's own verify line requires a location, not a name. */
    location: string;
    evidence: string;
    remediation: string;
    verification: string;
}

export interface Skipped {
    check: string;
    tier: Tier;
    /** The SITE TYPE, verbatim — 2.3 requires the type to be the stated reason. */
    reason: string;
}

/**
 * An applicable check the instrument could not decide.
 *
 * NOT a finding (nothing was established) and NOT a pass (nothing was cleared).
 * The third state exists because a detector that guesses on an undecidable input
 * is worse than one that abstains — and because a pass this checker did not earn
 * is exactly the silent-green defect its own header names.
 */
export interface Undecided {
    check: string;
    tier: Tier;
    /** `file:line` the instrument stopped at, so the reader can look at it. */
    location: string;
    reason: string;
    /** WHY it could not decide — see `UndecidedReason`. Never a fifth state. */
    reason_class: UndecidedReason;
}

/**
 * The two ways a check can fail to decide. A REASON CLASS on the existing
 * `Undecided` state, deliberately not a new state.
 *
 * `instrument-limit`   the input carries no evidence this reader can consume.
 *                      A static reader looking for `<img>` in a tree with no
 *                      HTML page is not finding zero violations — it is
 *                      reading zero bytes, and those are different answers.
 * `declaration-missing` the evidence is readable, but the CALLER declared
 *                      nothing that would settle which rule applies to it.
 */
export type UndecidedReason = 'instrument-limit' | 'declaration-missing';

/** A tier the region axis moved, and why. Reported so the axis is visible. */
export interface Escalated {
    check: string;
    from: Tier;
    to: Tier;
    why: string;
}

export interface Report {
    site_type: SiteType;
    region: Region;
    enabled: boolean;
    findings: Finding[];
    skipped: Skipped[];
    /** Checks that applied and found nothing. */
    passed: string[];
    /** Applicable checks with no implementation yet — never counted as passed. */
    unimplemented: string[];
    /** Applicable, implemented, and undecidable on THIS input. Never a pass. */
    unknown: Undecided[];
    /** Tiers the region axis raised. Empty on `unspecified`, by construction. */
    escalated: Escalated[];
    scanned_files: number;
}

export interface Escalation {
    check: string;
    region: Region;
    to: Tier;
    why: string;
    /** Same contract as `CheckDef` — an escalation row is a legal claim too. */
    authority?: string;
    review_by?: string;
}

/* -- 2.1/2.2: a legal claim carries its own authority and expiry ------------ */

/**
 * A statute reference: a named instrument, or a numbered article/section.
 *
 * The list is deliberately short and abbreviation-shaped. A broader "any legal
 * word" match would fire on `regulatory exposure` and turn every jurisdictional
 * sentence into a citation the gate then demands a source for — which is how a
 * scoped gate becomes a blanket one nobody can satisfy. The numbered-provision
 * arm (`Art. 13`, `§ 5`) catches an instrument the list does not name yet.
 *
 * `TMG` is retained as a token on purpose, and this is a HISTORICAL NOTE rather
 * than a citation: the statute was superseded by the DDG in May 2024, so a row
 * that names it again is exactly what this detector must still catch.
 */
export const STATUTE_RE =
    /\b(TMG|DDG|TTDSG|TDDDG|DSGVO|GDPR|BDSG|RDG|UWG|BGB|HGB|StGB|CCPA|CPRA|HIPAA|ePrivacy|DSA|DMA|BFSG|EAA)\b|(?:\bArt\.|\bArticle\b|§)\s*\d/;

/** A config row that may assert a legal basis: a check, or a region escalation. */
export interface LegalRow {
    kind: 'check' | 'escalation' | 'supersession';
    id: string;
    why: string;
    authority?: string;
    review_by?: string;
}

const ISO_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Today, as an ISO date, through the repository's one sanctioned clock seam.
 *
 * NOT `new Date()`: a lapsed-date verdict read off the wall clock is a verdict
 * that greens on Monday and reds on Friday from the same tree, which is the
 * defect `lint_deterministic_time` exists to keep out of a gate. `asOf()`
 * resolves `--as-of`, `AC_AS_OF`, the commit date under CI, and only then the
 * wall clock — with its own non-reproducibility warning attached.
 */
export function asOfToday(): string {
    return asOf().toISOString().slice(0, 10);
}

/** Every row of the config that could carry a legal claim, in report order. */
export function legalRowsOf(doc: {
    checks?: CheckDef[];
    regions?: { escalations?: Escalation[] };
    supersessions?: Supersession[];
}): LegalRow[] {
    const rows: LegalRow[] = [];
    for (const c of doc.checks ?? []) {
        rows.push({
            kind: 'check',
            id: c.id,
            why: c.why ?? '',
            ...(c.authority === undefined ? {} : { authority: c.authority }),
            ...(c.review_by === undefined ? {} : { review_by: c.review_by }),
        });
    }
    for (const e of doc.regions?.escalations ?? []) {
        rows.push({
            kind: 'escalation',
            id: `${e.check}@${e.region}`,
            why: e.why ?? '',
            ...(e.authority === undefined ? {} : { authority: e.authority }),
            ...(e.review_by === undefined ? {} : { review_by: e.review_by }),
        });
    }
    // A supersession row IS a statute claim by construction: it names the
    // provision a page cites and the one that replaced it. Policed always,
    // whatever its `why` says.
    for (const t of doc.supersessions ?? []) {
        rows.push({
            kind: 'supersession',
            id: t.id,
            why: `${t.cites} -> ${t.replaced_by}`,
            ...(t.authority === undefined ? {} : { authority: t.authority }),
            ...(t.review_by === undefined ? {} : { review_by: t.review_by }),
        });
    }
    return rows;
}

/**
 * The legal-row contract, as a list of violations (empty = clean).
 *
 * Three obligations, and the third is the one that makes the other two more
 * than decoration:
 *
 *   1. a row whose `why` NAMES a statute must carry `authority` and `review_by`;
 *   2. `authority` and `review_by` travel together — a citation with no expiry
 *      is the comment this contract exists to replace, and an expiry with no
 *      citation dates nothing. This half is what keeps the contract intact when
 *      the statute moves OUT of the prose and INTO `authority`;
 *   3. a `review_by` on or after `asOf` is live; anything earlier is LAPSED and
 *      is a violation rather than a warning. A date nothing reads is a comment,
 *      and this repository already documents a warning ignored eighteen times.
 *
 * A row that asserts no legal basis is not policed. The gate is scoped, not
 * blanket: demanding a citation from `A framework default error page loses the
 * visitor` would make the contract unsatisfiable and therefore ignorable.
 */
export function legalRowViolations(rows: readonly LegalRow[], asOf: string): string[] {
    const out: string[] = [];
    for (const r of rows) {
        const namesStatute = STATUTE_RE.test(r.why);
        const hasAuthority = (r.authority ?? '').trim().length > 0;
        const hasDate = (r.review_by ?? '').trim().length > 0;
        const where = `${r.kind} "${r.id}"`;
        // One violation per MISSING FIELD, never one per rule that noticed it.
        // Dropping `authority` from a statute row trips both obligation 1 and
        // obligation 2, and reporting it twice would make the count a property
        // of the rule set rather than of the config.
        const isLegal = namesStatute || hasAuthority || hasDate;
        if (isLegal && !hasAuthority) {
            out.push(
                `${where}: carries no \`authority\` — ` +
                    (namesStatute
                        ? 'its `why` names a statute, and a citation with no source is a comment rather than a claim anyone can re-check.'
                        : 'a `review_by` with no citation dates nothing.'),
            );
        }
        if (isLegal && !hasDate) {
            out.push(
                `${where}: carries no \`review_by\` — ` +
                    (namesStatute
                        ? 'its `why` names a statute, and the citation has no date by which it must be re-read.'
                        : 'an undated citation cannot go stale visibly.'),
            );
        }
        if (!hasDate) continue;
        const date = (r.review_by ?? '').trim();
        if (!ISO_DATE_RE.test(date) || Number.isNaN(Date.parse(date))) {
            out.push(`${where}: \`review_by\` is "${date}", which is not an ISO YYYY-MM-DD date.`);
            continue;
        }
        if (date < asOf) {
            out.push(
                `${where}: \`review_by\` lapsed on ${date} (as of ${asOf}) — re-read the citation, ` +
                    'then move the date. Overdue is a finding, not a silent pass.',
            );
        }
    }
    return out;
}

export function loadConfig(root = REPO_ROOT): {
    checks: CheckDef[];
    siteTypes: SiteType[];
    regions: Region[];
    escalations: Escalation[];
    supersessions: Supersession[];
} {
    const abs = path.join(root, CONFIG_REL);
    let raw: string;
    try {
        raw = fs.readFileSync(abs, 'utf-8');
    } catch {
        throw new DeadScopeError(
            'check_web_launch_readiness',
            `${CONFIG_REL} is missing — the config IS this command's corpus, and an absent ` +
                'one cannot be read as "no checks to run".',
        );
    }
    const doc = JSON.parse(raw) as {
        checks?: CheckDef[];
        site_types?: { values?: SiteType[] };
        regions?: { values?: Region[]; escalations?: Escalation[] };
        supersessions?: Supersession[];
    };
    const checks = doc.checks ?? [];
    const siteTypes = doc.site_types?.values ?? [];
    if (checks.length === 0 || siteTypes.length === 0) {
        throw new DeadScopeError(
            'check_web_launch_readiness',
            `${CONFIG_REL} carries no checks or no site types — an empty corpus checks nothing.`,
        );
    }
    const regions = doc.regions?.values ?? [];
    const escalations = doc.regions?.escalations ?? [];
    if (regions.length === 0) {
        throw new DeadScopeError(
            'check_web_launch_readiness',
            `${CONFIG_REL} carries no region axis — a DE site would silently get the ` +
                'situational tier for a legally owed page.',
        );
    }
    const basis = basisViolations(checks);
    if (basis.length > 0) {
        throw new DeadScopeError('check_web_launch_readiness', `${CONFIG_REL} carries a check with no usable basis:\n  - ${basis.join('\n  - ')}`);
    }
    const legal = legalRowViolations(legalRowsOf(doc), asOfToday());
    if (legal.length > 0) {
        // A gate that audited a site while shipping an unbacked legal claim of
        // its own would be auditing from a position it has not earned.
        throw new DeadScopeError(
            'check_web_launch_readiness',
            `${CONFIG_REL} ships a legal claim the row cannot back:\n  - ${legal.join('\n  - ')}`,
        );
    }
    return { checks, siteTypes, regions, escalations, supersessions: doc.supersessions ?? [] };
}

/**
 * Apply the region escalation to a check's tier.
 *
 * Returns the escalated tier and the reason, or the original tier and null. The
 * reason travels with the tier because a reader seeing `required-legal-pages`
 * as CRITICAL on one run and SITUATIONAL on another needs the axis that moved
 * it, not just the outcome.
 */
export function tierFor(
    c: CheckDef,
    region: Region,
    escalations: readonly Escalation[],
): { tier: Tier; escalatedBy: string | null } {
    const e = escalations.find((x) => x.check === c.id && x.region === region);
    return e === undefined ? { tier: c.tier, escalatedBy: null } : { tier: e.to, escalatedBy: e.why };
}

/**
 * The `web_launch_readiness:` block of `.agent-settings.yml`, as read.
 *
 * `site_type` and `region` join `enabled` here because they were CLI-ONLY, and
 * that is D12: a consumer could set `enabled: true`, run the gate, and get
 * `required-legal-pages` at SITUATIONAL — non-blocking, exit 0 — while the same
 * finding is CRITICAL and blocking for a DE-targeted site. The escalation was
 * not overridden; it was never reachable, because `--region` defaults to
 * `unspecified` and no settings key could say otherwise.
 *
 * `undefined` means the key is ABSENT, which is a different fact from
 * `region: 'unspecified'` — the first is a caller who said nothing, the second
 * a caller who said "no jurisdiction". `render()` distinguishes them.
 */
export interface WebLaunchSettings {
    enabled: boolean;
    site_type?: SiteType;
    region?: Region;
}

/** Two-space keys under `web_launch_readiness:` in `.agent-settings.yml`. */
export function readSettings(root: string): WebLaunchSettings {
    let raw: string;
    try {
        raw = fs.readFileSync(path.join(root, '.agent-settings.yml'), 'utf-8');
    } catch {
        return { enabled: false };
    }
    const out: WebLaunchSettings = { enabled: false };
    let inSection = false;
    for (const line of raw.split('\n')) {
        if (/^web_launch_readiness:\s*$/.test(line)) {
            inSection = true;
            continue;
        }
        if (/^\S/.test(line)) {
            inSection = false;
            continue;
        }
        if (!inSection) continue;
        if (/^\s{2}enabled:\s*true\s*$/.test(line)) out.enabled = true;
        const st = /^\s{2}site_type:\s*["']?([a-z-]+)["']?\s*$/.exec(line);
        if (st !== null) out.site_type = st[1] as SiteType;
        const rg = /^\s{2}region:\s*["']?([a-z]+)["']?\s*$/.exec(line);
        if (rg !== null) out.region = rg[1] as Region;
    }
    return out;
}

/** `web_launch_readiness.enabled: true` in `.agent-settings.yml` — default OFF. */
export function enabled(root: string): boolean {
    return readSettings(root).enabled;
}

/* -- staging indexability: the check that predates the IMPLS table --------- */

export interface Located {
    file: string;
    line: number;
    text: string;
}

/** The extensions the indexability pass reads: markup, robots.txt, sitemaps and source modules. */
const INDEXABLE_RE = /\.(html?|txt|xml|js|jsx|ts|tsx|vue|svelte|astro)$/i;

/** The crawler register for `root`, cached per root and day. */
const CRAWLER_CACHE = new Map<string, CrawlerRow[]>();
export function crawlersFor(root: string): CrawlerRow[] {
    const key = `${root}|${asOfToday()}`;
    const hit = CRAWLER_CACHE.get(key);
    if (hit !== undefined) return hit;
    let rows: CrawlerRow[];
    try {
        rows = loadCrawlerRegister(root);
    } catch (e) {
        throw new DeadScopeError('check_web_launch_readiness', (e as Error).message);
    }
    CRAWLER_CACHE.set(key, rows);
    return rows;
}

/**
 * Indexability leftovers in a build directory, each with a `file:line`.
 *
 * `undecided` holds blocks that rest on a crawler-register row past its
 * `review_by`: whether they hide the site from search is unknown, not clean.
 */
export function scanIndexability(
    buildDir: string,
    root = REPO_ROOT,
): { hits: Located[]; undecided: Located[]; files: number } {
    const files = readTree(buildDir).filter((f) => INDEXABLE_RE.test(f.base));
    const r = indexability(files, crawlersFor(root), asOfToday());
    return { hits: r.hits, undecided: r.undecided, files: files.length };
}


/* ── the remaining checks (2.2 and 2.3) ─────────────────────────────────────── */

/**
 * Every scannable file in a build directory, read once.
 *
 * The single walk replaces the per-check walk the one-check version could get
 * away with: eight checks each walking the tree is eight times the IO for the
 * same bytes, and — worse — eight chances for the walkers to disagree about
 * what counts as a file.
 */
export interface SourceFile {
    rel: string;
    base: string;
    text: string;
    lines: string[];
}

const SCANNABLE_RE = /\.(html?|css|txt|xml|js|jsx|ts|tsx|vue|svelte|astro|md)$/i;

export function readTree(buildDir: string): SourceFile[] {
    const out: SourceFile[] = [];
    const walk = (dir: string): void => {
        let entries: fs.Dirent[];
        try {
            entries = fs.readdirSync(dir, { withFileTypes: true });
        } catch {
            return;
        }
        for (const e of entries.sort((a, b) => a.name.localeCompare(b.name))) {
            const abs = path.join(dir, e.name);
            if (e.isDirectory()) {
                if (e.name === 'node_modules' || e.name === '.git') continue;
                walk(abs);
                continue;
            }
            if (!SCANNABLE_RE.test(e.name)) continue;
            let text: string;
            try {
                text = fs.readFileSync(abs, 'utf-8');
            } catch {
                continue;
            }
            out.push({
                rel: path.relative(buildDir, abs),
                base: e.name.toLowerCase(),
                text,
                lines: text.split('\n'),
            });
        }
    };
    walk(buildDir);
    return out;
}

/** An HTML page, as opposed to a robots.txt or a source module. */
function isPage(f: SourceFile): boolean {
    return /\.html?$/i.test(f.base);
}

/**
 * A check's implementation: files in, located hits out.
 *
 * Returning an EMPTY array means "applied and found nothing" — which is a pass.
 * A check that cannot decide must not return an empty array; it must not be in
 * `IMPLEMENTED` at all, so it reports as unimplemented instead. That is the one
 * rule keeping the silent-green defect out of this table.
 */
type Impl = (files: readonly SourceFile[], tp?: ThirdPartyCtx, crawlers?: readonly CrawlerRow[]) => Located[];

/** `http://` on a host we serve, excluding the XML/DTD namespace URLs. */
const INSECURE_ASSET_RE =
    /(?:src|href|action)\s*=\s*["']http:\/\/(?!localhost|127\.0\.0\.1|schemas?\.|www\.w3\.org)/i;

const httpsEnforcement: Impl = (files) => {
    const hits: Located[] = [];
    for (const f of files) {
        if (!isPage(f)) continue;
        f.lines.forEach((line, i) => {
            if (INSECURE_ASSET_RE.test(line)) {
                hits.push({ file: f.rel, line: i + 1, text: line.trim().slice(0, 160) });
            }
        });
    }
    return hits;
};

/**
 * A custom 404 page exists somewhere in the build.
 *
 * A whole-tree question, not a per-file one, so the hit it reports is located at
 * the build root rather than at a file — an absence has no line number, and
 * inventing one would be worse than admitting the shape of the finding.
 */
const customErrorRoute: Impl = (files) => {
    const found = files.some((f) => /^(404|not-found)(\.html?|\/index\.html?)?$/i.test(f.rel.replace(/\\/g, '/')) || /(^|\/)404\.html?$/i.test(f.rel));
    return found ? [] : [{ file: '.', line: 0, text: 'no 404.html or not-found page in the build output' }];
};

/** The first `<meta>` whose `name` is `name`, in any attribute order. */
function metaNamed(text: string, name: string): string | undefined {
    for (const t of tagsOf(text, HEAD_TAGS)) {
        if (t.closed && t.name === 'meta' && (attr(t.tag, 'name') ?? '').trim().toLowerCase() === name) return t.tag;
    }
    return undefined;
}

/**
 * Per-route title and description, and the DUPLICATE case counts.
 *
 * The obvious implementation checks presence. Presence is the easy half: a
 * layout that puts one hard-coded title on every route passes a presence check
 * and is exactly the defect the step names ("per-route"). So a title shared by
 * more than one page is a hit, with both locations reported.
 */
const perRouteMetadata: Impl = (files) => {
    const hits: Located[] = [];
    const titles = new Map<string, string[]>();
    for (const f of files) {
        if (!isPage(f)) continue;
        const title = titleOf(f.text);
        if (title === undefined) {
            hits.push({ file: f.rel, line: lineOf(f, '<title'), text: 'no <title> on this page' });
        } else {
            const key = title.toLowerCase();
            titles.set(key, [...(titles.get(key) ?? []), f.rel]);
        }
        const desc = metaNamed(f.text, 'description');
        if (desc === undefined || (attr(desc, 'content') ?? '').trim() === '') {
            hits.push({
                file: f.rel,
                line: lineOf(f, 'name="description"'),
                text: 'no <meta name="description"> on this page',
            });
        }
    }
    for (const [title, where] of titles) {
        if (where.length < 2) continue;
        hits.push({
            file: where[0] ?? '.',
            line: 0,
            text: `title "${title}" is shared by ${String(where.length)} pages (${where.join(', ')}) — present, but not per-route`,
        });
    }
    return hits;
};

/** Content images without alt. `alt=""` is DECORATIVE and deliberately valid. */
const IMG_RE = /<img\b[^>]*>/gi;
const imageAlternativeText: Impl = (files) => {
    const hits: Located[] = [];
    for (const f of files) {
        if (!isPage(f)) continue;
        f.lines.forEach((line, i) => {
            for (const tag of line.match(IMG_RE) ?? []) {
                // `alt=""` is the ARIA-correct marking for a decorative image
                // and must NOT be a finding: flagging it would push authors to
                // write filler alt text, which is worse for a screen reader
                // than the empty string that tells it to skip.
                if (/\balt\s*=/i.test(tag)) continue;
                hits.push({ file: f.rel, line: i + 1, text: tag.slice(0, 160) });
            }
        });
    }
    return hits;
};

const documentHeadBasics: Impl = (files) => {
    const hits: Located[] = [];
    for (const f of files) {
        if (!isPage(f)) continue;
        if (!/<html[^>]+\blang\s*=\s*["'][a-z]/i.test(f.text)) {
            hits.push({ file: f.rel, line: lineOf(f, '<html'), text: 'no lang on <html>' });
        }
        if (!tagsOf(f.text, HEAD_TAGS).some((t) => t.closed && t.name === 'meta' && attr(t.tag, 'charset') !== undefined)) {
            hits.push({ file: f.rel, line: lineOf(f, '<head'), text: 'no <meta charset>' });
        }
        if (metaNamed(f.text, 'viewport') === undefined) {
            hits.push({ file: f.rel, line: lineOf(f, '<head'), text: 'no <meta name="viewport">' });
        }
    }
    return hits;
};

/** `nosnippet` / `max-snippet:0` on an indexable page — eligible for search, ineligible for its snippet. */
const snippetEligibility: Impl = (files, _tp, crawlers) => {
    const rows = crawlers ?? crawlersFor(REPO_ROOT);
    const today = asOfToday();
    return files.filter(isPage).flatMap((f) => snippetBlocks(f.rel, f.text, rows, today).hits);
};

const LEGAL_DE = [/impressum/i, /datenschutz/i];
const LEGAL_GENERIC = [/privacy/i, /(terms|imprint|legal)/i];

/**
 * The legally owed pages exist.
 *
 * Matched on the PATH, never on page text: a link to `/impressum` from a footer
 * is not an Impressum, and a check that accepted the link would pass every site
 * that links to a page it never built.
 */
const requiredLegalPages: Impl = (files) => {
    const paths = files.map((f) => f.rel.replace(/\\/g, '/'));
    const missing: string[] = [];
    const has = (res: RegExp[]): boolean => res.every((re) => paths.some((p) => re.test(p)));
    if (!has(LEGAL_DE) && !has(LEGAL_GENERIC)) {
        if (!paths.some((p) => /impressum|imprint|legal/i.test(p))) missing.push('imprint/Impressum');
        if (!paths.some((p) => /datenschutz|privacy/i.test(p))) missing.push('privacy/Datenschutz');
    }
    return missing.length === 0
        ? []
        : [{ file: '.', line: 0, text: `no page found for: ${missing.join(', ')}` }];
};

/**
 * Analytics loads only behind consent — INCLUDING the load order (3.1).
 *
 * The row's own `verification` field asks for the runtime assertion: *"Load the
 * page with consent declined and assert no request to the analytics origin."*
 * A static reader cannot load a page. The strongest assertion it CAN make is
 * source order within one document, so that is what it makes — and where even
 * that is undecidable it returns `unknown` (3.2) rather than a pass.
 *
 * What the ordering pass covers, stated so the message can say it: the position
 * of the measurement tag relative to the gate script INSIDE one file. What it
 * does not cover: runtime order, deferred or dynamic imports, order established
 * by a bundler across files, and anything a minifier put on one line — each of
 * which produces an `unknown`, never a silent pass.
 */
const ANALYTICS_RE = /(googletagmanager\.com|google-analytics\.com|gtag\(|plausible\.io|matomo|segment\.com|hotjar)/i;
const CONSENT_RE = /(consent|cookiebanner|cookie-banner|cookieconsent|klaro|usercentrics|borlabs|osano)/i;

/**
 * A line that can actually LOAD something, as opposed to prose about loading.
 *
 * `consent-order-bad` says the word *consent* in its `<meta description>` and
 * still fires: a sentence describing a gate is not a gate, and a positional
 * detector that counted it would report a correctly ordered page while the tag
 * fires first. Applied to markup only — every line of a `.js` file is code.
 */
const EXECUTABLE_LINE_RE = /<script\b|\bsrc\s*=|\bimport\b|\brequire\s*\(|\.js\b/i;

/** Past this, a line is a bundler artefact and its internal order is not source order. */
const MINIFIED_LINE_CHARS = 400;

interface ConsentOrder {
    hits: Located[];
    undecided: Located[];
}

function analyseConsentOrder(files: readonly SourceFile[]): ConsentOrder {
    const hits: Located[] = [];
    const undecided: Located[] = [];
    // Prose is excluded from BOTH sides, and the fixture is why: a `.md` file
    // in the build tree describing the consent banner matched CONSENT_RE, so
    // the check reported a pass on a fixture seeded to fire it. Documentation
    // saying a thing exists is not the thing existing — and the same argument
    // runs the other way, so an analytics name mentioned in a README must not
    // count as analytics either.
    const code = files.filter((f) => !/\.md$/i.test(f.base));
    const loadable = (f: SourceFile, line: string): boolean => !isPage(f) || EXECUTABLE_LINE_RE.test(line);
    const firstLoad = (f: SourceFile, re: RegExp): number =>
        f.lines.findIndex((l) => re.test(l) && loadable(f, l));
    const anyConsent = code.some((f) => firstLoad(f, CONSENT_RE) >= 0);

    for (const f of code) {
        const a = firstLoad(f, ANALYTICS_RE);
        if (a < 0) continue;
        if (!anyConsent) {
            // Unchanged from the pre-3.1 behaviour, and still the sharpest
            // finding available: nothing in the build can gate the tag.
            f.lines.forEach((line, i) => {
                if (!ANALYTICS_RE.test(line) || !loadable(f, line)) return;
                hits.push({
                    file: f.rel,
                    line: i + 1,
                    text:
                        `${line.trim().slice(0, 120)} — analytics is loaded here and no consent mechanism ` +
                        'was found anywhere in the build, so nothing can gate it. Source order was not the ' +
                        'question: there is no gate to be ordered against.',
                });
            });
            continue;
        }
        const c = firstLoad(f, CONSENT_RE);
        const aLine = f.lines[a] ?? '';
        if (c < 0) {
            undecided.push({
                file: f.rel,
                line: a + 1,
                text:
                    'analytics is loaded here and the consent mechanism lives in another file. Which of ' +
                    'the two the browser runs first is decided by the bundler and the page, not by source ' +
                    'order across files, and a static read cannot establish it.',
            });
            continue;
        }
        if (c === a) {
            undecided.push({
                file: f.rel,
                line: a + 1,
                text:
                    'the analytics tag and the consent gate are on the SAME line, so line order cannot ' +
                    'separate them. Ordering is undecidable on this input.',
            });
            continue;
        }
        if (aLine.length > MINIFIED_LINE_CHARS) {
            undecided.push({
                file: f.rel,
                line: a + 1,
                text:
                    `this line is ${String(aLine.length)} characters, i.e. minified — the order inside a ` +
                    'bundler artefact is not the source order this pass reads.',
            });
            continue;
        }
        if (a < c) {
            hits.push({
                file: f.rel,
                line: a + 1,
                text:
                    `${aLine.trim().slice(0, 120)} — the analytics tag is at line ${String(a + 1)}, ` +
                    `ABOVE the consent gate at line ${String(c + 1)} of the same file, so it is reached ` +
                    'before consent can be recorded. Source order inside this file is what was checked; ' +
                    'runtime order, dynamic imports and cross-file bundler order were not.',
            });
        }
    }
    return { hits, undecided };
}

const analyticsAndConsent: Impl = (files) => analyseConsentOrder(files).hits;

/**
 * Checks that can report `unknown`, and the probe that decides when they do.
 *
 * A separate table rather than a widened `Impl` signature: the invariant that an
 * EMPTY `Located[]` means "applied and found nothing" is what keeps the
 * silent-green defect out of `IMPLS`, and folding a third state into that return
 * type would put the invariant back in play for all eight implementations.
 *
 * EVERY check has an entry, and the entries are NOT interchangeable. Measured
 * on this tree before the table was filled: a build holding only `index.js` and
 * `src/App.vue` — one `<img>` with no alt, no `<title>`, no `lang`, no charset,
 * no viewport, no canonical — produced
 *
 *     PASSED: staging-noindex-leftover, https-enforcement, per-route-metadata,
 *             image-alternative-text, document-head-basics,
 *             canonical-and-sitemap-coherence, analytics-and-consent-wiring
 *     exit 0
 *
 * Five of those iterated ZERO files, because `isPage()` filtered every file out.
 * The `Impl` contract above states the rule they broke in its own words, and
 * `audit()` turned each empty array into a pass.
 *
 * The probes are keyed to EVIDENCE SURFACE, not to one shared blindness
 * predicate. An AI council (2026-09-04, 2/2, anthropic + openai) rejected the
 * single predicate: "no HTML page" is honest for a check that reads rendered
 * markup and semantically wrong for one that matches route paths, where the
 * absence of HTML does not establish the absence of a route surface. Four
 * surfaces, nine checks.
 */
interface UndecideHit extends Located {
    reason_class: UndecidedReason;
    /**
     * The instrument could not read this check's evidence surface AT ALL, so
     * whatever the `Impl` returned came from the same zero evidence and must
     * not be reported.
     *
     * Without this, `custom-error-route` on a component-rendered build reports
     * "no 404.html in the build output" as a HIGH finding AND, two lines lower,
     * that the absence of the file establishes nothing. Both sentences are
     * printed from the same read, and one of them is wrong. A PER-LOCATION
     * undecided (the consent-order pass) is the opposite case: other locations
     * were decided, so its findings stand and the cover legitimately overlaps.
     */
    surface_blind?: true;
}
export interface UndecideCtx {
    region: Region;
    siteType: SiteType;
    escalations: readonly Escalation[];
    /** Register + supersession table; loaded from the repository when absent. */
    thirdParty?: ThirdPartyCtx;
    /** The crawler register; loaded from the repository when absent. */
    crawlers?: readonly CrawlerRow[];
}
export type Undecide = (files: readonly SourceFile[], ctx: UndecideCtx) => UndecideHit[];

/** Surface 1 — anything at all was read. */
const readAnything = (files: readonly SourceFile[]): boolean => files.length > 0;

/** Surface 2 — a rendered HTML page exists, so markup is inspectable. */
const hasPage = (files: readonly SourceFile[]): boolean => files.some(isPage);

/** Surface 3 — code the consent pass can read at all (`.md` is prose, not code). */
const hasCode = (files: readonly SourceFile[]): boolean => files.some((f) => !/\.md$/i.test(f.base));

const ROUTE_DIR_RE = /(^|\/)(routes?|pages)(\/|$)/i;
const ROUTER_FILE_RE = /^(router|routes)\.(js|jsx|ts|tsx|mjs|cjs)$/i;

/**
 * Surface 4 — a statically inspectable ROUTE surface.
 *
 * Enumerated rather than described, because a predicate is only as good as the
 * artefacts it names: an HTML page, a `sitemap.xml`, a `routes/` or `pages/`
 * tree, or a router module. None of the four present means a 404 route or a
 * legal page can exist entirely inside a client bundle, and its absence AS A
 * FILE establishes nothing. One of the four present and the absence IS the
 * finding — which is why this is not the markup predicate wearing another name.
 */
const hasRouteSurface = (files: readonly SourceFile[]): boolean =>
    files.some(
        (f) =>
            isPage(f) ||
            f.base === 'sitemap.xml' ||
            ROUTE_DIR_RE.test(f.rel.replace(/\\/g, '/')) ||
            ROUTER_FILE_RE.test(f.base),
    );

/** A whole-tree undecided: an absence has no line, and inventing one would lie. */
const blind = (text: string, reason_class: UndecidedReason = 'instrument-limit'): UndecideHit[] => [
    { file: '.', line: 0, text, reason_class, surface_blind: true },
];

/** `p(files)` true → decidable, no entry. False → one whole-tree undecided. */
const unless = (p: (f: readonly SourceFile[]) => boolean, text: string): Undecide =>
    (files) => (p(files) ? [] : blind(text));

const NO_MARKUP =
    'no HTML page in this build tree, so this check read zero bytes rather than finding zero ' +
    'violations. Markup is produced by components or a template engine that a static reader ' +
    'does not evaluate';

export const UNDECIDABLE: Readonly<Record<string, Undecide>> = {
    'staging-noindex-leftover': unless(
        readAnything,
        'the build tree holds no scannable file at all — "no indexability leftover" would be a ' +
            'verdict on zero bytes. This check reads .js/.ts/.vue too, so a page-only predicate ' +
            'would understate what it can normally see.',
    ),
    'https-enforcement': unless(hasPage, `${NO_MARKUP}, so an insecure asset URL is invisible here rather than absent.`),
    'per-route-metadata': unless(hasPage, `${NO_MARKUP}, and a head manager sets <title> and description at runtime.`),
    'image-alternative-text': unless(hasPage, `${NO_MARKUP}, so an <img> with no alt cannot be reached.`),
    'document-head-basics': unless(hasPage, `${NO_MARKUP}, and lang/charset/viewport come from a shell this reader does not resolve.`),
    'canonical-and-sitemap-coherence': unless(hasPage, `${NO_MARKUP}, and rel="canonical" is commonly injected at runtime.`),
    'custom-error-route': unless(
        hasRouteSurface,
        'no statically inspectable route surface — no HTML page, no sitemap.xml, no routes/ or ' +
            'pages/ tree, no router module. A 404 route may exist only inside a client bundle, so ' +
            'its absence as a FILE establishes nothing.',
    ),
    'required-legal-pages': (files, ctx) => {
        if (!hasRouteSurface(files)) {
            return blind(
                'no statically inspectable route surface — no HTML page, no sitemap.xml, no ' +
                    'routes/ or pages/ tree, no router module. A legal page matched on its PATH ' +
                    'cannot be found in a tree that publishes no paths.',
            );
        }
        // The declaration arm, and it is D12's silent loss stated precisely.
        // The matcher accepts EITHER the DE pair (Impressum + Datenschutz) or
        // the generic pair (privacy + terms/imprint/legal). A tree carrying only
        // the generic pair passes at every region — including `de`, where an
        // Impressum is owed by name. With no region declared, whether the
        // generic pair discharges the obligation is a question about the
        // CALLER, not about the tree, and the instrument must not answer it.
        const paths = files.map((f) => f.rel.replace(/\\/g, '/'));
        const all = (res: RegExp[]): boolean => res.every((re) => paths.some((p) => re.test(p)));
        const registered = ctx.escalations.some((e) => e.check === 'required-legal-pages');
        if (ctx.region === 'unspecified' && registered && all(LEGAL_GENERIC) && !all(LEGAL_DE)) {
            return blind(
                'this build carries the generic legal pair (privacy + terms/imprint/legal) and ' +
                    'NOT the DE pair (Impressum + Datenschutz), and no region was declared. The ' +
                    'config registers a region escalation for this check, so the answer depends on ' +
                    'a declaration the caller did not make: pass `--region` or set ' +
                    '`web_launch_readiness.region` in .agent-settings.yml.',
                'declaration-missing',
            );
        }
        return [];
    },
    'analytics-and-consent-wiring': (files) => {
        if (!hasCode(files)) {
            return blind(
                'the build tree holds no code file at all (prose is excluded from this pass by ' +
                    'construction), so neither a measurement tag nor a consent gate could be read.',
            );
        }
        return analyseConsentOrder(files).undecided.map((u) => ({ ...u, reason_class: 'instrument-limit' as const }));
    },
    'third-party-load-in-markup': (files, ctx) => {
        if (!files.some((f) => isPage(f) || isStylesheet(f))) {
            return blind(`${NO_MARKUP}, and no stylesheet either, so a third-party load is invisible here rather than absent.`);
        }
        return classifyLoads(files, thirdPartyOf(ctx).register).undecided.map((u) => ({
            ...u,
            reason_class: 'instrument-limit' as const,
        }));
    },
    // Blind only where NO page is readable. A build with pages and no imprint
    // is decidable for these rows: there is nothing cited, and the missing page
    // is `required-legal-pages`'s finding, not an undecided here.
    'superseded-statute-in-legal-page': unless(hasPage, `${NO_MARKUP}, so no imprint citation could be read.`),
    'placeholder-in-legal-page': unless(hasPage, `${NO_MARKUP}, so no legal-page template token could be read.`),
    // Per location as well: a snippet block resting on a lapsed crawler row is
    // unknown, never a silent pass (the same reading `metaNoindex` gives it).
    'snippet-eligibility': (files, ctx) => {
        if (!hasPage(files)) return blind(`${NO_MARKUP}, and robots meta tags are commonly set by a head manager at runtime.`);
        const rows = ctx.crawlers ?? crawlersFor(REPO_ROOT);
        return files
            .filter(isPage)
            .flatMap((f) => snippetBlocks(f.rel, f.text, rows, asOfToday()).undecided)
            .map((u) => ({ ...u, reason_class: 'instrument-limit' as const }));
    },
    'structured-data-parses': unless(hasPage, `${NO_MARKUP}, so no JSON-LD block could be read.`),
    'privacy-page-provider-coverage': (files, ctx) => {
        if (!files.some((f) => isPage(f) || isStylesheet(f))) {
            return blind(`${NO_MARKUP}, so which providers load could not be read.`);
        }
        return privacyCoverage(files, thirdPartyOf(ctx).register).undecided.map((u) => ({
            ...u,
            reason_class: 'instrument-limit' as const,
        }));
    },
};

const isStylesheet = (f: SourceFile): boolean => /\.css$/i.test(f.base);

/** The register and supersession table for `root`, cached per root. */
const TP_CACHE = new Map<string, ThirdPartyCtx>();
export function thirdPartyFor(root: string): ThirdPartyCtx {
    // Keyed on the date too: a lapsed register row must fail the run that asks
    // on the day it lapsed, not be served from a cache filled the day before.
    const key = `${root}|${asOfToday()}`;
    const hit = TP_CACHE.get(key);
    if (hit !== undefined) return hit;
    let register: OriginRow[];
    try {
        register = loadRegister(root, asOfToday());
    } catch (e) {
        throw new DeadScopeError('check_web_launch_readiness', (e as Error).message);
    }
    const tp: ThirdPartyCtx = { register, supersessions: loadConfig(root).supersessions };
    TP_CACHE.set(key, tp);
    return tp;
}
const thirdPartyOf = (ctx: UndecideCtx): ThirdPartyCtx => ctx.thirdParty ?? thirdPartyFor(REPO_ROOT);
const tpOrRepo = (tp?: ThirdPartyCtx): ThirdPartyCtx => tp ?? thirdPartyFor(REPO_ROOT);

/** First line containing `needle`, 1-indexed; 1 when absent (an absence has no line). */
function lineOf(f: SourceFile, needle: string): number {
    const i = f.lines.findIndex((l) => l.toLowerCase().includes(needle.toLowerCase()));
    return i < 0 ? 1 : i + 1;
}

export const IMPLS: Readonly<Record<string, Impl>> = {
    'https-enforcement': httpsEnforcement,
    'custom-error-route': customErrorRoute,
    'per-route-metadata': perRouteMetadata,
    'image-alternative-text': imageAlternativeText,
    'document-head-basics': documentHeadBasics,
    'canonical-and-sitemap-coherence': canonicalAndSitemap,
    'required-legal-pages': requiredLegalPages,
    'analytics-and-consent-wiring': analyticsAndConsent,
    'third-party-load-in-markup': (files, tp) => classifyLoads(files, tpOrRepo(tp).register).findings,
    'superseded-statute-in-legal-page': (files, tp) => supersededStatute(files, tpOrRepo(tp).supersessions),
    'placeholder-in-legal-page': (files) => legalPagePlaceholders(files),
    'privacy-page-provider-coverage': (files, tp) => privacyCoverage(files, tpOrRepo(tp).register).findings,
    'snippet-eligibility': snippetEligibility,
    'structured-data-parses': structuredDataParses,
};

/** Checks with a real implementation. Everything else reports UNIMPLEMENTED. */
export const IMPLEMENTED: readonly string[] = [
    'staging-noindex-leftover',
    ...Object.keys(IMPLS),
];

export function audit(
    buildDir: string,
    siteType: SiteType,
    root = REPO_ROOT,
    region: Region = 'unspecified',
    /**
     * The blind-spot probe table, overridable so a test can DELETE one entry
     * and observe that check fall back to `passed`.
     *
     * That reversal is the whole proof the predicates are narrow: an entry that
     * cannot be removed without the fixture staying undecided was never doing
     * the work, and a probe that answers `undecided` on every input is as
     * useless as one that answers `passed` on every input — only harder to
     * notice. Same shape as `root` and `region`: defaulted, so no caller
     * changes.
     */
    undecidable: Readonly<Record<string, Undecide>> = UNDECIDABLE,
): Report {
    const { checks, siteTypes, regions, escalations } = loadConfig(root);
    const thirdParty = thirdPartyFor(root);
    if (!siteTypes.includes(siteType)) {
        throw new DeadScopeError(
            'check_web_launch_readiness',
            `unknown site type "${siteType}" — registered: ${siteTypes.join(', ')}`,
        );
    }
    if (!regions.includes(region)) {
        throw new DeadScopeError(
            'check_web_launch_readiness',
            `unknown region "${region}" — registered: ${regions.join(', ')}`,
        );
    }
    const findings: Finding[] = [];
    const skipped: Skipped[] = [];
    const passed: string[] = [];
    const unimplemented: string[] = [];
    const unknown: Undecided[] = [];
    const escalated: Escalated[] = [];
    // ONE walk for every check. Eight walkers over the same bytes is eight
    // times the IO and eight chances to disagree about what counts as a file.
    const files = readTree(buildDir);

    for (const c of checks) {
        const { tier, escalatedBy } = tierFor(c, region, escalations);
        if (escalatedBy !== null) {
            escalated.push({ check: c.id, from: c.tier, to: tier, why: escalatedBy });
        }
        if (!c.applies_to.includes(siteType)) {
            // The site type IS the reason, verbatim. 2.3 requires exactly this.
            skipped.push({ check: c.id, tier, reason: `site type is ${siteType}` });
            continue;
        }
        if (!IMPLEMENTED.includes(c.id)) {
            // Never counted as passed: an unimplemented check that reported
            // "clean" would be the silent-green defect this repository names.
            unimplemented.push(c.id);
            continue;
        }
        const impl = IMPLS[c.id];
        const index = impl === undefined ? scanIndexability(buildDir, root) : undefined;
        const hits = index === undefined ? (impl as Impl)(files, thirdParty, crawlersFor(root)) : index.hits;
        const undecided: UndecideHit[] = [
            ...(undecidable[c.id]?.(files, { region, siteType, escalations, thirdParty, crawlers: crawlersFor(root) }) ?? []),
            ...(index?.undecided ?? []).map((u) => ({ ...u, reason_class: 'instrument-limit' as const })),
        ];
        for (const u of undecided) {
            unknown.push({
                check: c.id,
                tier,
                location: `${u.file}:${String(u.line)}`,
                reason: u.text,
                reason_class: u.reason_class,
            });
        }
        if (hits.length === 0 && undecided.length === 0) {
            passed.push(c.id);
            continue;
        }
        // A surface-blind probe read nothing, so the Impl's hits came from the
        // same nothing. Reporting them alongside "this establishes nothing"
        // would print two contradictory sentences from one read.
        if (undecided.some((u) => u.surface_blind === true)) continue;
        for (const h of hits) {
            findings.push({
                check: c.id,
                tier,
                location: `${h.file}:${String(h.line)}`,
                evidence: h.text,
                remediation: c.remediation,
                verification: c.verification,
            });
        }
    }
    const report: Report = {
        site_type: siteType,
        region,
        enabled: enabled(root),
        findings,
        skipped,
        passed,
        unimplemented,
        unknown,
        escalated,
        scanned_files: files.length,
    };
    assertEveryCheckAccounted(report, checks);
    return report;
}

/** The five report buckets, as a set of check ids each. */
export function bucketsOf(r: Report): Readonly<Record<string, ReadonlySet<string>>> {
    return {
        findings: new Set(r.findings.map((f) => f.check)),
        passed: new Set(r.passed),
        unimplemented: new Set(r.unimplemented),
        unknown: new Set(r.unknown.map((u) => u.check)),
        skipped: new Set(r.skipped.map((s) => s.check)),
    };
}

/**
 * Every configured check lands in at least one bucket — enforced HERE, not only
 * in a test, because a test is not present in a consumer's run.
 *
 * A COVER, not a partition. A check can be in `findings` AND `unknown` at once:
 * `audit()` pushes both and only short-circuits to `passed` when both are empty.
 * Asserting disjointness would therefore red a correct report.
 *
 * Compared by check ID rather than by cardinality, because duplicate entries can
 * make two counts agree while a check has silently vanished — the exact failure
 * the report's own `passed`/`unimplemented` split exists to prevent. An AI
 * council (2026-09-04, 2/2) chose the throw over a report field: exposing the
 * gap as data makes the consumer responsible for noticing what it cannot
 * reliably detect, and a check that lands nowhere reads as green.
 *
 * The error carries the missing ids AND the buckets built so far, so a
 * diagnosis does not lose the findings that were already computed.
 */
export function assertEveryCheckAccounted(r: Report, checks: readonly CheckDef[]): void {
    const buckets = bucketsOf(r);
    const seen = new Set<string>();
    for (const ids of Object.values(buckets)) for (const id of ids) seen.add(id);
    const configured = new Set(checks.map((c) => c.id));
    const missing = [...configured].filter((id) => !seen.has(id)).sort();
    const stray = [...seen].filter((id) => !configured.has(id)).sort();
    if (missing.length === 0 && stray.length === 0) return;
    const where = Object.entries(buckets)
        .map(([k, v]) => `${k}=[${[...v].sort().join(', ')}]`)
        .join(' · ');
    throw new DeadScopeError(
        'check_web_launch_readiness',
        'the report does not account for every configured check, so some result would have ' +
            'been read as clean by omission.' +
            (missing.length > 0 ? `\n  in no bucket: ${missing.join(', ')}` : '') +
            (stray.length > 0 ? `\n  in a bucket but not configured: ${stray.join(', ')}` : '') +
            `\n  buckets built so far: ${where}`,
    );
}

const TIER_ORDER: readonly Tier[] = ['critical', 'high', 'medium', 'situational'];

/** Report order: critical → high → medium → situational-applicable → skipped. */
export function render(r: Report): string {
    const out: string[] = [];
    out.push(`site type: ${r.site_type}  ·  region: ${r.region}`);
    if (r.region === 'unspecified') {
        // 2.2. The axis that decides SEVERITY is invisible when it is absent,
        // and an invisible axis reads as "no escalation applies" rather than as
        // "nobody said". `escalated` is empty on `unspecified` BY CONSTRUCTION,
        // so silence here is exactly the shape of the lost escalation.
        out.push(
            '  region unspecified → DE escalation not active. Every tier below is the base tier; ' +
                'declare `--region de` or `web_launch_readiness.region` to raise the ones the ' +
                'config registers.',
        );
    }
    for (const e of r.escalated) {
        // Printed BEFORE the findings, because a reader who sees a check at
        // CRITICAL on one run and SITUATIONAL on another needs the axis that
        // moved it, not just the outcome.
        out.push(`  escalated by region: ${e.check} ${e.from} → ${e.to} — ${e.why}`);
    }
    for (const tier of TIER_ORDER) {
        const f = r.findings.filter((x) => x.tier === tier);
        if (f.length === 0) continue;
        out.push('', `${tier.toUpperCase()} (${String(f.length)})`);
        for (const x of f) {
            out.push(`  ${x.location}  ${x.check}`);
            out.push(`    evidence:     ${x.evidence}`);
            out.push(`    remediation:  ${x.remediation}`);
            out.push(`    verification: ${x.verification}`);
        }
    }
    if (r.unknown.length > 0) {
        // Printed with the findings rather than with the passes, because an
        // undecided check is an open question about the site — not a clearance.
        out.push('', `UNDECIDED — applicable, audited, and not decidable from this build (${String(r.unknown.length)})`);
        for (const u of r.unknown) {
            out.push(`  ${u.location}  ${u.check}`);
            out.push(`    unknown: ${u.reason}`);
        }
    }
    if (r.passed.length > 0) out.push('', `PASSED: ${r.passed.join(', ')}`);
    if (r.unimplemented.length > 0) {
        out.push('', `NOT YET IMPLEMENTED (applicable, not audited): ${r.unimplemented.join(', ')}`);
    }
    if (r.skipped.length > 0) {
        out.push('', 'SKIPPED — not applicable to this site type');
        for (const s of r.skipped) out.push(`  ${s.check}: ${s.reason}`);
    }
    return out.join('\n');
}

export function main(argv: string[] = process.argv.slice(2), root = REPO_ROOT): number {
    const prepared = prepare(argv, root);
    return typeof prepared === 'number' ? prepared : finish(prepared, argv);
}

/**
 * The `--render` path (road-to-a-page-that-says-what-it-loads 3.1): the static
 * audit, then the offline render witness, reconciled into one report.
 */
export async function mainAsync(argv: string[] = process.argv.slice(2), root = REPO_ROOT): Promise<number> {
    if (!argv.includes('--render')) return main(argv, root);
    const prepared = prepare(argv, root);
    if (typeof prepared === 'number') return prepared;
    const build = argv[argv.indexOf('--build') + 1] ?? '';
    const witness = await renderWitness(build);
    return finish(applyRenderWitness(prepared, witness, thirdPartyFor(root).register), argv);
}

const TPL = 'third-party-load-in-markup';

/**
 * Fold the render witness into a static report. Pure, so it is tested without a
 * browser.
 *
 * - `unverified` → one undecided for the row, never a pass.
 * - A static undecided "next to a consent gate" is DECIDED: requested on first
 *   paint → a finding; never requested → dropped, the gate did its job.
 * - A registered provider requested at runtime that static reading missed
 *   (script-injected) → a finding; an unregistered one → undecided.
 */
export function applyRenderWitness(r: Report, w: Witness, register: readonly OriginRow[]): Report {
    const check = loadedRow(r);
    if (check === null) return r;
    const tier = check.tier;
    if (w.status !== 'ok') {
        return {
            ...r,
            passed: r.passed.filter((id) => id !== TPL),
            unknown: [
                ...r.unknown,
                { check: TPL, tier, location: '.:0', reason: `render witness unverified: ${w.reason ?? 'unknown reason'}`, reason_class: 'instrument-limit' },
            ],
        };
    }
    const requestedHosts = new Set(w.requests.map((q) => new URL(q.url).host.toLowerCase()));
    const hostOf = (text: string): string | undefined => /`([^`]+)`/.exec(text)?.[1]?.toLowerCase();
    const findings = [...r.findings];
    const unknown: Undecided[] = [];
    for (const u of r.unknown) {
        const host = u.check === TPL && /consent or click-to-load/.test(u.reason) ? hostOf(u.reason) : undefined;
        if (host === undefined) {
            unknown.push(u);
            continue;
        }
        if (requestedHosts.has(host)) {
            findings.push({
                check: TPL,
                tier,
                location: u.location,
                evidence: `requests \`${host}\` on first paint with no interaction and no consent given (render witness), although a gate sits in the same file.`,
                remediation: check.remediation,
                verification: check.verification,
            });
        }
    }
    const statedHosts = new Set(
        [...findings, ...r.unknown].filter((x) => x.check === TPL).map((x) => hostOf('evidence' in x ? x.evidence : x.reason)),
    );
    for (const q of w.requests) {
        const url = new URL(q.url);
        const host = url.host.toLowerCase();
        if (statedHosts.has(host)) continue;
        statedHosts.add(host);
        const row = resolveOrigin(url, register);
        if (row === undefined) {
            unknown.push({ check: TPL, tier, location: `${q.page}:0`, reason: `requests \`${host}\` at runtime, an unknown third party; its provider is undecided.`, reason_class: 'instrument-limit' });
            continue;
        }
        findings.push({
            check: TPL,
            tier,
            location: `${q.page}:0`,
            evidence: `requests \`${host}\` (${row.provider}) on first paint at runtime (render witness); no static line names it, so a script adds it.`,
            remediation: check.remediation,
            verification: check.verification,
        });
    }
    const decided = !findings.some((f) => f.check === TPL) && !unknown.some((u) => u.check === TPL);
    const passed = r.passed.filter((id) => id !== TPL);
    return { ...r, findings, unknown, passed: decided ? [...passed, TPL] : passed };
}

/** The configured row for the third-party check, if it applied to this run. */
function loadedRow(r: Report): CheckDef | null {
    if (r.skipped.some((s) => s.check === TPL)) return null;
    const row = loadConfig().checks.find((c) => c.id === TPL);
    if (row === undefined) return null;
    const tier = r.findings.find((f) => f.check === TPL)?.tier ?? r.unknown.find((u) => u.check === TPL)?.tier ??
        r.escalated.find((e) => e.check === TPL)?.to ?? row.tier;
    return { ...row, tier };
}

function prepare(argv: string[], root: string): number | Report {
    const arg = (f: string): string | undefined => {
        const i = argv.indexOf(f);
        return i >= 0 ? argv[i + 1] : undefined;
    };
    const build = arg('--build');
    // CLI first, settings second, default last. A flag is an explicit statement
    // about THIS run; a settings key is a standing declaration about the
    // project; the default is nobody saying anything, and only the last of the
    // three is silent about a jurisdiction.
    const settings = readSettings(root);
    const siteType = (arg('--site-type') ?? settings.site_type) as SiteType | undefined;
    const region = (arg('--region') ?? settings.region ?? 'unspecified') as Region;
    if (build === undefined || siteType === undefined) {
        process.stderr.write(
            'usage: check_web_launch_readiness --build <dir> --site-type <type> ' +
                '[--region <de|eu|us|unspecified>] [--render] [--json]\n' +
                '  --site-type and --region also resolve from `web_launch_readiness:` in ' +
                '.agent-settings.yml; a flag overrides the file.\n',
        );
        return 2;
    }
    if (!settings.enabled && !argv.includes('--force')) {
        process.stdout.write(
            'web-launch-readiness is DEFAULT-OFF until the pre-registered benchmark returns\n' +
                'positive (claim:web-launch-readiness-finds-more, status unbacked). Enable with\n' +
                '`web_launch_readiness.enabled: true` in .agent-settings.yml, or pass --force.\n',
        );
        return 0;
    }
    let r: Report;
    try {
        r = audit(build, siteType, root, region);
        reportScanned({
            gate: 'check_web_launch_readiness',
            scanned: r.scanned_files,
            units: 'build file(s)',
            roots: [build],
            allowEmpty:
                'OPTIONAL_INPUT: a build directory may legitimately hold no scannable file ' +
                'when the caller points at an unbuilt tree; a missing config is a separate ' +
                'hard error in loadConfig()',
        });
    } catch (e) {
        if (e instanceof DeadScopeError) {
            process.stderr.write(`❌  ${e.message}\n`);
            return 2;
        }
        throw e;
    }
    return r;
}

function finish(r: Report, argv: string[]): number {
    if (argv.includes('--json')) {
        process.stdout.write(`${JSON.stringify(r, null, 2)}\n`);
    } else {
        process.stdout.write(`${render(r)}\n`);
    }
    const blocking = r.findings.filter((f) => f.tier === 'critical' || f.tier === 'high');
    // An UNDECIDED applicable check exits non-zero whatever its tier. Exiting 0
    // would report the run as clean on a question the instrument never answered,
    // which is the same silent-green failure as counting an unimplemented check
    // as passed — the tier axis grades findings, and this is not one.
    return blocking.length > 0 || r.unknown.length > 0 ? 1 : 0;
}

if (path.resolve(process.argv[1] ?? '') === path.resolve(HERE)) {
    void mainAsync().then((code) => process.exit(code));
}
"}
